async function classTestsFn(){const{data,error}=await sb.functions.invoke('student-class-tests',{body:{action:'summary'}});if(error)throw new Error(error.message||'تعذر تحميل اختبارات الحصص');if(data?.error)throw new Error(data.message||data.error);return data}
function testPctMeta(v){if(v==null)return{label:'غير مسجل',cls:'mutedPill',color:'#64748b'};const n=Number(v);if(n>=85)return{label:'ممتاز',cls:'good',color:'#16a34a'};if(n>=70)return{label:'جيد',cls:'mid',color:'#2563eb'};if(n>=50)return{label:'يحتاج تحسين',cls:'warn',color:'#f59e0b'};return{label:'يحتاج مراجعة',cls:'bad',color:'#ef4444'}}
function testStatusMeta(r){if(r.status==='absent')return{label:'غائب',cls:'bad'};if(r.status==='scored'){const m=testPctMeta(r.percentage);return{label:m.label,cls:m.cls}}return{label:'غير مسجل',cls:'mutedPill'}}
function testAnalysisIcon(k){return k==='excellent'?'🌟':k==='good'?'✅':k==='improve'?'📘':k==='alert'?'⚠️':'📊'}
function testTypeLabel(v){return v||'اختبار'}
function renderClassTests(d){const s=d.summary||{},perf=d.performance||{},avg=s.average_percentage,m=testPctMeta(avg);$('testsAverage').textContent=pctText(avg);$('testsScoreCircle').style.setProperty('--score',Math.max(0,Math.min(100,Number(avg||0))));$('testsScoreCircle').style.setProperty('--ring',m.color);$('testsPerformanceTitle').textContent=perf.title||'اختبارات الحصص';$('testsPerformanceText').textContent=perf.message||'يتم الحساب من الدرجات المسجلة.';$('testsPerformanceBadge').textContent=avg==null?'لا توجد درجات':m.label;$('testsPerformanceBadge').style.borderColor=m.color;$('testsScored').textContent=s.scored_tests||0;$('testsScoredDetail').textContent=`من ${s.total_tests||0} اختبار مرتبط بحصصك`;$('testsBest').textContent=pctText(s.best_percentage);$('testsLatest').textContent=pctText(s.latest_percentage);$('testsLatestDetail').textContent=s.latest_percentage==null?'لا توجد نتيجة مسجلة':`${s.latest_score??'—'} / ${s.latest_max_score??'—'}`;$('testsAbsent').textContent=s.absent_tests||0;$('testsAnalysisIcon').textContent=testAnalysisIcon(perf.kind);$('testsAnalysisTitle').textContent=perf.title||'تحليل الأداء';$('testsAnalysisText').textContent=perf.message||'';$('testsTrendText').textContent=d.trend?.message||'';
const types=d.by_type||[];$('testsTypes').innerHTML=types.length?types.map(x=>`<div class="testsTypeCard"><span class="small muted">${esc(testTypeLabel(x.label))}</span><b>${pctText(x.avg_percentage)}</b><div class="small muted">${Number(x.scored||0)} بدرجة · ${Number(x.absent||0)} غياب · ${Number(x.total||0)} إجمالي</div></div>`).join(''):'<div class="empty" style="grid-column:1/-1">لا توجد أنواع اختبارات مسجلة حتى الآن.</div>';
const last=d.last5||[];$('testsTimeline').innerHTML=last.length?last.map(r=>{const sm=testStatusMeta(r);const score=r.status==='scored'?`${Number(r.score)} / ${Number(r.max_score)} · ${pctText(r.percentage)}`:r.status==='absent'?'غائب عن الاختبار':'الدرجة غير مسجلة';return `<div class="testsTimelineItem"><div class="name">${esc(r.test_name||r.test_type_label||'اختبار')}</div><div class="date">${dateShort(r.session_date)} · حصة ${Number(r.session_number)}</div><span class="testsPill ${sm.cls}">${esc(sm.label)}</span><div class="small" style="margin-top:8px">${esc(score)}</div></div>`}).join(''):'<div class="empty" style="grid-column:1/-1">لا توجد اختبارات مرتبطة بحصصك حتى الآن.</div>';
const rows=d.tests||[];$('testsDetails').innerHTML=rows.length?'<div class="testsHead"><div>التاريخ</div><div>الاختبار</div><div>النوع</div><div>الدرجة</div><div>النسبة</div><div>الحالة</div></div>'+rows.map(r=>{const sm=testStatusMeta(r);return `<div class="testsRow"><div>${dateShort(r.session_date)}</div><div><b>${esc(r.test_name||'اختبار')}</b><div class="small muted">الحصة ${Number(r.session_number)}${r.session_title?' · '+esc(r.session_title):''}</div></div><div>${esc(r.test_type_label||r.test_type||'اختبار')}</div><div>${r.status==='scored'?esc(Number(r.score)+' / '+Number(r.max_score)):'—'}</div><div>${r.status==='scored'?pctText(r.percentage):'—'}</div><div><span class="testsPill ${sm.cls}">${esc(sm.label)}</span></div></div>`}).join(''):'<div class="empty">لا توجد اختبارات مسجلة لك حتى الآن.</div>';$('testsFootnote').textContent='متوسط الدرجات يُحسب من الاختبارات التي لها درجة مسجلة فقط. الغياب يظهر منفصلًا ولا يُحوّل تلقائيًا إلى درجة صفر داخل المتوسط.'}
async function openClassTestsView(){clearMsg();showOnly('classTestsView');$('classTestsLoading').innerHTML='<div class="empty">جاري تحميل نتائج الاختبارات...</div>';$('classTestsLoading').classList.remove('hidden');$('classTestsContent').classList.add('hidden');try{const d=await classTestsFn();renderClassTests(d);$('classTestsLoading').classList.add('hidden');$('classTestsContent').classList.remove('hidden')}catch(e){$('classTestsLoading').innerHTML='<div class="msg err">'+esc(e.message||'تعذر تحميل اختبارات الحصص')+'</div>'}}
